const DUR = s => s.replace(/(\d+)h/g, "$1س").replace(/(\d+)m\b/g, "$1د");

// Arabic counted nouns: 1 → "يوم واحد", 2 → "يومان", 3–10 → "5 أيام", 11–99 → "14 يومًا", 100+ → "100 يوم".
const NOUNS = {
  day: ["يوم واحد", "يومان", "أيام", "يومًا", "يوم", "يومين"],
  week: ["أسبوع واحد", "أسبوعان", "أسابيع", "أسبوعًا", "أسبوع", "أسبوعين"],
  hour: ["ساعة واحدة", "ساعتان", "ساعات", "ساعة", "ساعة", "ساعتين"],
  minute: ["دقيقة واحدة", "دقيقتان", "دقائق", "دقيقة", "دقيقة", "دقيقتين"],
  habit: ["عادة واحدة", "عادتان", "عادات", "عادة", "عادة", "عادتين"],
  event: ["موعد واحد", "موعدان", "مواعيد", "موعدًا", "موعد", "موعدين"],
  rakah: ["ركعة واحدة", "ركعتان", "ركعات", "ركعة", "ركعة", "ركعتين"],
  time: ["مرة واحدة", "مرتان", "مرات", "مرة", "مرة", "مرتين"]
};
// gen = true after a preposition or in a construct ("آخر يومين", "قبل ساعتين"): two takes -ين.
export function count(n, noun, gen) {
  n = +n;
  const w = NOUNS[noun];
  if (n === 1) return w[0];
  if (n === 2) return gen ? w[5] : w[1];
  const r = n % 100;
  if (n === 0 || (r >= 3 && r <= 10)) return n + " " + w[2];
  if (r >= 11) return n + " " + w[3];
  return n + " " + w[4];
}

