  [/^(Suhoor, fasting, iftar at Maghrib, (?:Taraweeh|Dua al-Iftitah) & daily juz) — switches on by itself in Ramadan(?: · (.+))?$/, (m) => (/Iftitah/.test(m[1]) ? "السحور والصيام والإفطار عند المغرب ودعاء الافتتاح وجزء يومي" : "السحور والصيام والإفطار عند المغرب والتراويح وجزء يومي") + " — يتفعّل تلقائيًا في رمضان" + (m[2] ? " · " + m[2].replace("Ramadan Mubarak! Active now", "رمضان مبارك! مفعّل الآن").replace(/Ramadan in ~(\d+) days/, (_, n) => "رمضان بعد نحو " + count(n, "day", true)) : "")]
